import type { Ctx } from '../context'
import type { Queryable } from '../db'

// ---------------------------------------------------------------------------
// Images and videos for the firm blog: cover images (uploaded or generated by
// AI) and media placed inside an article. In the article text a media item is
// a line of its own: ![caption](media:<id>) for an uploaded image or video, or
// ![caption](https://youtube.com/…) for a YouTube or Vimeo video.
// ---------------------------------------------------------------------------

export type MediaKind = 'image' | 'video'
export type MediaRef = { url: string; kind: MediaKind }

// Recognises the file from its first bytes, not from its name or the browser's claim.
export function sniffMedia(b: Uint8Array): { kind: MediaKind; mime: string } | null {
  const ascii = (from: number, to: number) => String.fromCharCode(...b.subarray(from, to))
  if (b[0] === 0x89 && ascii(1, 4) === 'PNG') return { kind: 'image', mime: 'image/png' }
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return { kind: 'image', mime: 'image/jpeg' }
  if (ascii(0, 4) === 'RIFF' && ascii(8, 12) === 'WEBP') return { kind: 'image', mime: 'image/webp' }
  if (ascii(0, 4) === 'GIF8') return { kind: 'image', mime: 'image/gif' }
  if (ascii(4, 8) === 'ftyp') return { kind: 'video', mime: ascii(8, 10) === 'qt' ? 'video/quicktime' : 'video/mp4' }
  if (b[0] === 0x1a && b[1] === 0x45 && b[2] === 0xdf && b[3] === 0xa3) return { kind: 'video', mime: 'video/webm' }
  return null
}

export const MEDIA_LINE = /^!\[([^\]\n]{0,300})\]\((media:([0-9a-f-]{36})|https?:\/\/[^\s)]+)\)$/i

// YouTube and Vimeo links become privacy-friendly embeds; anything else is not embedded.
export function embedUrl(link: string): string | null {
  let u: URL
  try { u = new URL(link) } catch { return null }
  const host = u.hostname.replace(/^(www\.|m\.)/, '')
  let id: string | null = null
  if (host === 'youtu.be') id = u.pathname.slice(1)
  else if (host === 'youtube.com' || host === 'youtube-nocookie.com') {
    id = u.searchParams.get('v') ?? u.pathname.match(/^\/(?:embed|shorts|live)\/([^/]+)/)?.[1] ?? null
  }
  if (id && /^[\w-]{6,20}$/.test(id)) return `https://www.youtube-nocookie.com/embed/${id}`
  if (host === 'vimeo.com' || host === 'player.vimeo.com') {
    const v = u.pathname.match(/(\d{5,12})/)?.[1]
    if (v) return `https://player.vimeo.com/video/${v}`
  }
  return null
}

export function mediaIdsIn(...texts: (string | null | undefined)[]): string[] {
  const ids = new Set<string>()
  for (const t of texts) for (const m of String(t ?? '').matchAll(/\]\(media:([0-9a-f-]{36})\)/gi)) ids.add(m[1]!.toLowerCase())
  return [...ids]
}

// Looks up the media an article uses, for rendering with the given URL scheme.
export async function mediaResolver(db: Queryable, orgId: string, texts: (string | null | undefined)[], urlFor: (id: string) => string) {
  const ids = mediaIdsIn(...texts)
  const rows = ids.length ? await db.query('SELECT id, kind FROM blog_media WHERE org_id = $1 AND id = ANY($2::uuid[])', [orgId, ids]) : []
  const map = new Map<string, MediaRef>(rows.map((r) => [String(r.id), { url: urlFor(String(r.id)), kind: r.kind }]))
  return (id: string) => map.get(id.toLowerCase())
}

export function coverPrompt(p: { title?: string | null; excerpt?: string | null; style?: string | null; jurisdiction?: string | null }) {
  return [
    `Editorial cover image for a law firm's blog article titled "${(p.title ?? '').slice(0, 200)}".`,
    p.excerpt ? `The article is about: ${p.excerpt.slice(0, 500)}` : '',
    p.style === 'photo' ? 'Style: realistic, high-quality professional photograph.' : 'Style: clean, modern editorial illustration with a restrained palette.',
    p.jurisdiction ? `Setting: professional, suitable for a Gulf / Middle East audience (${p.jurisdiction}).` : 'Setting: professional, suitable for a Gulf / Middle East audience.',
    'Landscape composition. Absolutely no text, letters, numbers, logos, flags or watermarks. No identifiable real people. Respectful and culturally appropriate.'
  ].filter(Boolean).join(' ')
}

// Streams a media item, honouring HTTP Range requests so videos can seek.
export async function serveMedia(c: Ctx, db: Queryable, where: { id: string; orgId: string }, cache: string) {
  const [meta] = await db.query('SELECT mime, size FROM blog_media WHERE id = $1 AND org_id = $2', [where.id, where.orgId])
  if (!meta) return c.body(null, 404)
  const size = Number(meta.size)
  const range = c.req.header('range')?.match(/^bytes=(\d*)-(\d*)$/)
  c.header('content-type', meta.mime)
  c.header('accept-ranges', 'bytes')
  c.header('cache-control', cache)
  c.header('x-content-type-options', 'nosniff')
  if (range && (range[1] || range[2])) {
    let start = range[1] ? Number(range[1]) : Math.max(0, size - Number(range[2]))
    let end = range[1] && range[2] ? Math.min(Number(range[2]), size - 1) : size - 1
    if (start >= size || start > end) {
      c.header('content-range', `bytes */${size}`)
      return c.body(null, 416)
    }
    // At most 4 MB per response; players ask for the rest.
    end = Math.min(end, start + 4 * 1024 * 1024 - 1)
    const [row] = await db.query('SELECT substring(data FROM $3 FOR $4) AS part FROM blog_media WHERE id = $1 AND org_id = $2',
      [where.id, where.orgId, start + 1, end - start + 1])
    c.header('content-range', `bytes ${start}-${end}/${size}`)
    return c.body(new Uint8Array(row.part), 206)
  }
  const [row] = await db.query('SELECT data FROM blog_media WHERE id = $1 AND org_id = $2', [where.id, where.orgId])
  return c.body(new Uint8Array(row.data))
}
